mapper.select:
select t.id mainId, g.id, h.id as detailId, t.report_date, t.account_date, t.report_status, j.status reconciliationStatus, t.big_table_status, j.logistics_channel_id channelId, concat(j.logistics_supplier_name , '-',j.logistics_channel_name ) supplierName, j.so_code, k.instock_forecast_date, n.approve_date confirmTime, j.shop_id, j.country toCountry, g.sku_id, g.sku_no, cast(g.unit_cost AS NUMERIC(16, 6)) unit_cost, g.unit_currency, g.delivery_qty, cast(j.estimate_weight AS NUMERIC(16, 8)) billingWeight, j.estimate_weight_unit, cast(j.actual_billing_weight AS NUMERIC(16, 4)) billingWeightLogistics, cast(g.sku_weight AS NUMERIC(16, 4)) sku_weight, h.fee_type, cast(h.bill_amount_exchange AS NUMERIC(16, 4)) billAmount, cast(h.allocated_amount_exchange AS NUMERIC(16, 2)) allocatedAmount, cast(h.product_allocated_amount_exchange AS NUMERIC(16, 6)) productAllocatedAmount, h.fee_allocation_type, h.fee_allocation_type feeAllocationTypeName, h.weight_allocation_type, h.weight_allocation_type weightAllocationTypeName, t.update_user_name updateUserName, t.update_time updateTime, t.create_time createTime, h.allocated_currency currency from transfer_declare_cost_allocation_main t left join transfer_declare_cost_allocation g on t.id = g.main_id and g.is_deleted = false left join transfer_declare_cost_allocation_detail h on h.main_id = g.id and h.is_deleted = false left join tms_b2c_declare_reconciliation_detail j on t.declare_reconciliation_detail_id = j.id and j.is_deleted = false left join tms_b2c_declare_reconciliation n on n.id = j.main_id and n.is_deleted = false left join transfer_declare k on t.transfer_declare_id = k.id and k.is_deleted = false left join dict_basic l on h.fee_type = l.code and l.type = 'dictCostCategory'
${params.sqlMap.default} and t.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc,g.id,l.index asc
